"use client";

import { motion } from "framer-motion";

export default function Hero() {
  return (
    <section id="hero" className="relative overflow-hidden">
      <div className="absolute inset-0">
        <video
          className="h-full w-full object-cover"
          autoPlay
          muted
          loop
          playsInline
          preload="metadata"
          poster="/images/hero-poster.jpg"
          aria-label="Фоновое видео интерьера"
        >
          <source src="/video/hero.mp4" type="video/mp4" />
        </video>
        <div className="absolute inset-0 bg-anthracite/70" />
      </div>

      <div className="relative z-10 mx-auto flex min-h-[78vh] w-full max-w-6xl flex-col justify-center gap-8 px-4 py-24 text-beige sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, ease: "easeOut" }}
          className="max-w-2xl"
        >
          <p className="text-sm uppercase tracking-[0.3em] text-beige/70">
            Мебель премиум-класса на заказ
          </p>
          <h1 className="mt-4 font-heading text-4xl font-semibold leading-tight sm:text-5xl lg:text-6xl">
            Дизайн, производство и монтаж под ключ — без лишней суеты
          </h1>
          <p className="mt-4 text-lg text-beige/80 sm:text-xl">
            Проектируем мебель под стиль вашего пространства, фиксируем сроки и
            стоимость в договоре.
          </p>
        </motion.div>

        <div className="flex flex-wrap gap-4">
          <a
            href="#form"
            className="focus-ring rounded-full border border-gold/70 bg-gold px-6 py-3 text-sm font-semibold text-anthracite transition hover:bg-gold/90"
          >
            Рассчитать проект
          </a>
          <a
            href="#portfolio"
            className="focus-ring rounded-full border border-gold/70 px-6 py-3 text-sm font-semibold text-beige transition hover:border-gold"
          >
            Смотреть работы
          </a>
        </div>

        <div className="flex flex-wrap gap-3 text-sm text-beige/80">
          <span className="rounded-full border border-gold/50 px-4 py-2">
            Замер бесплатно
          </span>
          <span className="rounded-full border border-gold/50 px-4 py-2">
            Договор
          </span>
          <span className="rounded-full border border-gold/50 px-4 py-2">
            Гарантия
          </span>
        </div>
      </div>
    </section>
  );
}
