"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { furnitureTypes, leadSchema, type LeadFormValues } from "../../lib/validators";
import { track } from "../../lib/track";

type FormStatus = "idle" | "loading" | "success" | "error";

export default function LeadForm() {
  const [status, setStatus] = useState<FormStatus>("idle");
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<LeadFormValues>({
    resolver: zodResolver(leadSchema),
    defaultValues: {
      name: "",
      contact: "",
      furnitureType: "Кухня",
      comment: "",
      consent: false,
      honeypot: "",
    },
  });

  const onSubmit = async (values: LeadFormValues) => {
    setStatus("loading");
    track("lead_submit", { furnitureType: values.furnitureType });

    try {
      const response = await fetch("/api/lead", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(values),
      });

      if (!response.ok) {
        throw new Error("Request failed");
      }

      setStatus("success");
      track("lead_success");
      reset();
    } catch (error) {
      console.error(error);
      setStatus("error");
      track("lead_error");
    }
  };

  return (
    <section
      id="form"
      className="border-t border-gold/30 py-16 sm:py-20 lg:py-24"
    >
      <div className="mx-auto grid w-full max-w-6xl gap-10 px-4 sm:px-6 lg:px-8 lg:grid-cols-[1.1fr_0.9fr]">
        <div className="space-y-6">
          <div>
            <p className="text-sm uppercase tracking-[0.3em] text-anthracite/60">
              Расчет проекта
            </p>
            <h2 className="mt-3 font-heading text-3xl font-semibold sm:text-4xl">
              Получите персональный расчет и 3D-визуализацию
            </h2>
            <p className="mt-4 text-lg text-anthracite/80">
              Ответим в течение 15 минут, уточним детали и предложим варианты под
              ваш бюджет.
            </p>
          </div>

          <div className="grid gap-4 text-sm text-anthracite/70">
            <div className="rounded-2xl border border-gold/25 bg-white/70 p-4">
              Персональный менеджер ведет проект от замера до монтажа
            </div>
            <div className="rounded-2xl border border-gold/25 bg-white/70 p-4">
              Фиксируем сроки и стоимость в договоре
            </div>
            <div className="rounded-2xl border border-gold/25 bg-white/70 p-4">
              Гарантия до 5 лет и сервисное сопровождение
            </div>
          </div>
        </div>

        <form
          onSubmit={handleSubmit(onSubmit)}
          className="rounded-3xl border border-gold/30 bg-white/80 p-6"
          aria-live="polite"
        >
          <div className="space-y-5">
            <div>
              <label className="text-sm text-anthracite/70" htmlFor="name">
                Имя
              </label>
              <input
                id="name"
                type="text"
                placeholder="Как к вам обращаться"
                className="mt-2 w-full rounded-2xl border border-gold/40 bg-beige/80 px-4 py-3 text-base text-anthracite placeholder:text-anthracite/50 focus:border-gold focus:outline-none"
                {...register("name")}
                aria-invalid={Boolean(errors.name)}
                aria-describedby={errors.name ? "name-error" : undefined}
              />
              {errors.name && (
                <p id="name-error" className="mt-2 text-sm text-rose-300">
                  {errors.name.message}
                </p>
              )}
            </div>

            <div>
              <label className="text-sm text-anthracite/70" htmlFor="contact">
                Телефон или мессенджер (WhatsApp/Telegram)
              </label>
              <input
                id="contact"
                type="text"
                placeholder="+7 999 000-00-00 / @username"
                className="mt-2 w-full rounded-2xl border border-gold/40 bg-beige/80 px-4 py-3 text-base text-anthracite placeholder:text-anthracite/50 focus:border-gold focus:outline-none"
                {...register("contact")}
                aria-invalid={Boolean(errors.contact)}
                aria-describedby={errors.contact ? "contact-error" : undefined}
              />
              {errors.contact && (
                <p id="contact-error" className="mt-2 text-sm text-rose-300">
                  {errors.contact.message}
                </p>
              )}
            </div>

            <div>
              <label className="text-sm text-anthracite/70" htmlFor="furnitureType">
                Тип мебели
              </label>
              <select
                id="furnitureType"
                className="mt-2 w-full rounded-2xl border border-gold/40 bg-beige/80 px-4 py-3 text-base text-anthracite focus:border-gold focus:outline-none"
                {...register("furnitureType")}
                aria-invalid={Boolean(errors.furnitureType)}
                aria-describedby={
                  errors.furnitureType ? "furniture-type-error" : undefined
                }
              >
                {furnitureTypes.map((type) => (
                  <option key={type} value={type}>
                    {type}
                  </option>
                ))}
              </select>
              {errors.furnitureType && (
                <p id="furniture-type-error" className="mt-2 text-sm text-rose-300">
                  {errors.furnitureType.message}
                </p>
              )}
            </div>

            <div>
              <label className="text-sm text-anthracite/70" htmlFor="comment">
                Комментарий (необязательно)
              </label>
              <textarea
                id="comment"
                rows={4}
                placeholder="Пожелания по материалам, бюджету, срокам"
                className="mt-2 w-full resize-none rounded-2xl border border-gold/40 bg-beige/80 px-4 py-3 text-base text-anthracite placeholder:text-anthracite/50 focus:border-gold focus:outline-none"
                {...register("comment")}
                aria-invalid={Boolean(errors.comment)}
                aria-describedby={errors.comment ? "comment-error" : undefined}
              />
              {errors.comment && (
                <p id="comment-error" className="mt-2 text-sm text-rose-300">
                  {errors.comment.message}
                </p>
              )}
            </div>

            <div className="flex items-start gap-3">
              <input
                id="consent"
                type="checkbox"
                className="mt-1 h-4 w-4 rounded border-gold/40 bg-beige/80 text-gold focus:ring-gold"
                {...register("consent")}
                aria-invalid={Boolean(errors.consent)}
                aria-describedby={errors.consent ? "consent-error" : undefined}
              />
              <label className="text-sm text-anthracite/70" htmlFor="consent">
                Я согласен(а) с политикой обработки персональных данных
              </label>
            </div>
            {errors.consent && (
              <p id="consent-error" className="-mt-2 text-sm text-rose-300">
                {errors.consent.message}
              </p>
            )}

            <input
              type="text"
              tabIndex={-1}
              autoComplete="off"
              className="hidden"
              aria-hidden="true"
              {...register("honeypot")}
            />

            <button
              type="submit"
              className="focus-ring w-full rounded-full border border-gold/70 bg-gold px-6 py-3 text-sm font-semibold text-anthracite transition hover:bg-gold/90 disabled:cursor-not-allowed disabled:opacity-60"
              disabled={status === "loading"}
            >
              {status === "loading"
                ? "Отправляем заявку..."
                : "Рассчитать проект"}
            </button>

            {status === "success" && (
              <div className="rounded-2xl border border-emerald-400/30 bg-emerald-400/10 px-4 py-3 text-sm text-emerald-200">
                Заявка принята! Мы свяжемся с вами в ближайшее время.
              </div>
            )}

            {status === "error" && (
              <div className="rounded-2xl border border-rose-400/30 bg-rose-400/10 px-4 py-3 text-sm text-rose-200">
                Не удалось отправить заявку. Попробуйте еще раз или свяжитесь с
                нами по телефону.
              </div>
            )}
          </div>
        </form>
      </div>
    </section>
  );
}
